class Solution:

	def search(self, patt, S):
		arr = []
		d = 256
		q = 1000000007
		p = t = 0
		M = len(patt)
		N = len(S)
		h = d ** (M - 1) % q
		j = 0
		for i in range(M):
			p = (p * d + ord(patt[i])) % q
			t = (t * d + ord(S[i])) % q
		for i in range(N - M + 1):
			if p == t:
				while j < M:
					if S[i + j] != patt[j]:
						break
					else:
						j += 1
				if j == M:
					arr.append(i + 1)
			if i < N - M:
				t = (d * (t - ord(S[i]) * h) + ord(S[i + M])) % q
		if not len(arr):
			return [-1]
		return arr
